import copy
import datetime

from keystone.common import kvs
from keystone import exception
from keystone import token


class Token(kvs.Base, token.Driver):
    # Public interface
    def get_token(self, token_id):
        token = self.db.get('token-%s' % token_id)
        if (token and (token['expires'] is None
                       or token['expires'] > datetime.datetime.utcnow())):
            return token
        else:
            raise exception.TokenNotFound(token_id=token_id)

    def create_token(self, token_id, data):
        data_copy = copy.deepcopy(data)
        if 'expires' not in data:
            data_copy['expires'] = self._get_default_expire_time()
        self.db.set('token-%s' % token_id, data_copy)
        return copy.deepcopy(data_copy)

    def delete_token(self, token_id):
        try:
            return self.db.delete('token-%s' % token_id)
        except KeyError:
            raise exception.TokenNotFound(token_id=token_id)

    def list_tokens(self, user_id, tenant_id=None):
        tokens = []
        now = datetime.datetime.utcnow()
        for token, ref in self.db.items():
            if not token.startswith('token-'):
                continue
            if 'user' not in ref:
                continue
            if ref['user'].get('id') != user_id:
                continue
            if ref.get('expires') and ref.get('expires') < now:
                continue
            if tenant_id is not None:
                if 'tenant' not in ref:
                    continue
                if ref['tenant'].get('id') != tenant_id:
                    continue
            tokens.append(token.split('-', 1)[1])
        return tokens

